from collections import Counter, deque
def load_grids():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
import os,re,json
G=load_grids(); print(list(G))

def transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    # flood bg from border
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and g[ni][nj]==bg and not seen[ni][nj]:
                seen[ni][nj]=True; q.append((ni,nj))
    out=[r[:] for r in g]
    # interior bg components
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not seen[i][j]:
                comp=[]; qq=deque([(i,j)]); seen[i][j]=True
                while qq:
                    a,b=qq.popleft(); comp.append((a,b))
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+di,b+dj
                        if 0<=na<h and 0<=nb<w and g[na][nb]==bg and not seen[na][nb]:
                            seen[na][nb]=True; qq.append((na,nb))
                is_=[a for a,b in comp]; js=[b for a,b in comp]
                fh=len(is_)-min(is_)+1; fw=len(js)-min(js)+1
                fill=2 if fh==fw and fh%2==0 else 7
                for a,b in comp: out[a][b]=fill
    return out

